  // Special tree seeds
  TEAK(ItemID.TEAK_SEED, "Teak seed"),
  MAHOGANY(ItemID.MAHOGANY_SEED, "Mahogany seed"),
  CALQUAT(ItemID.CALQUAT_TREE_SEED, "Calquat tree seed"),
  CRYSTAL(ItemID.CRYSTAL_TREE_SEED, "Crystal acorn"),
